{"command":"cat <<'EOF' > math_test.go
package math

import "testing"

func TestDivide(t *testing.T) {
	type args struct {
		a int
		b int
	}
	tests := []struct {
		name    string
		args    args
		want    int
		wantErr bool
	}{
		{
			name: "div by zero",
			args: args{a: 10, b: 0},
			want: 0,
			wantErr: true,
		},
		{
			name: "10 / 2",
			args: args{a: 10, b: 2},
			want: 5,
			wantErr: false,
		},
	}
	for _, tt := range tests {
		got, err := Divide(tt.args.a, tt.args.b)
		if (err != nil) != tt.wantErr {
			t.Errorf("%q. Divide() error = %v, wantErr %v", tt.name, err, tt.wantErr)
			continue
		}
		if tt.wantErr {
			return
		}
		if got != tt.want {
			t.Errorf("%q. Divide() = %v, want %v", tt.name, got, tt.want)
		}
	}
}
EOF
go test -v math_test.go math.go"}

