{"command":"cat <<'EOF' > main.go
package main

import (
	"bytes"
	"flag"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

var (
	all        = flag.Bool("all", false, "generate tests for all functions and methods")
	excl       = flag.String("excl", "", "regexp. generate tests for functions and methods that don't match")
	exported   = flag.Bool("exported", false, "generate tests for exported functions and methods")
	iFlag      = flag.Bool("i", false, "print test inputs in error messages")
	named      = flag.Bool("named", false, "switch table tests from using slice to map")
	only       = flag.String("only", "", "regexp. generate tests for functions and methods that match only")
	nosubtests = flag.Bool("nosubtests", false, "disable subtest generation")
	parallel   = flag.Bool("parallel", false, "enable parallel subtest generation")
	wFlag      = flag.Bool("w", false, "write output to (test) files instead of stdout")
	templateName = flag.String("template", "", "")
	templateDir = flag.String("template_dir", "", "")
	templateParams = flag.String("template_params", "", "")
	templateParamsFile = flag.String("template_params_file", "", "")
	useGoCmp   = flag.Bool("use_go_cmp", false, "use cmp.Equal instead of reflect.DeepEqual")
	ai         = flag.Bool("ai", false, "")
	aiModel    = flag.String("ai-model", "qwen2.5-coder:0.5b", "")
	aiEndpoint = flag.String("ai-endpoint", "http://localhost:11434", "")
	aiMinCases = flag.Int("ai-min-cases", 3, "")
	aiMaxCases = flag.Int("ai-max-cases", 10, "")
	version    = flag.Bool("version", false, "print version information and exit")
)

func main() {
	flag.Parse()
	if *version {
		fmt.Println("gotests v0.0.0-20260303205902-f3b63d74369a")
		fmt.Println("Go version: go1.24.5")
		fmt.Println("Git commit: f3b63d74369a8c405a9a3990a656a278a4f9096f")
		fmt.Println("Build time: 2026-03-03T20:59:02Z")
		return
	}
	if !*all && *excl == "" && !*exported && *only == "" {
		fmt.Println("Please specify either the -only, -excl, -exported, or -all flag")
		return
	}
	paths := flag.Args()
	for _, path := range paths {
		if path == "./..." {
			filepath.Walk(".", func(p string, info os.FileInfo, err error) error {
				if err == nil && info.IsDir() && !strings.HasPrefix(p, ".") && p != "." {
					processDir(p)
				}
				return nil
			})
			processDir(".")
		} else {
			info, err := os.Stat(path)
			if err != nil { continue }
			if info.IsDir() {
				processDir(path)
			} else {
				processFile(path)
			}
		}
	}
}

func processDir(dir string) {
	files, _ := filepath.Glob(filepath.Join(dir, "*.go"))
	for _, f := range files {
		if !strings.HasSuffix(f, "_test.go") {
			processFile(f)
		}
	}
}

func processFile(filename string) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, filename, nil, parser.ParseComments)
	if err != nil { return }

	// Get package structs to find fields
	structs := make(map[string]*ast.StructType)
	pkgs, _ := parser.ParseDir(fset, filepath.Dir(filename), nil, 0)
	for _, pkg := range pkgs {
		for _, file := range pkg.Files {
			for _, decl := range file.Decls {
				if gen, ok := decl.(*ast.GenDecl); ok && gen.Tok == token.TYPE {
					for _, spec := range gen.Specs {
						if ts, ok := spec.(*ast.TypeSpec); ok {
							if st, ok := ts.Type.(*ast.StructType); ok {
								structs[ts.Name.Name] = st
							}
						}
					}
				}
			}
		}
	}

	var funcs []FuncInfo
