	if *onlyFlag != "" { if m, _ := regexp.MatchString(*onlyFlag, name); m { return true } }
	return *allFlag
}

func extractFuncInfo(fn *ast.FuncDecl, structs map[string]*ast.StructType) FuncInfo {
	info := FuncInfo{Name: fn.Name.Name, Parallel: *parallelFlag, Subtests: !*nosubtestsFlag, Named: *namedFlag, PrintInputs: *iFlag, UseGoCmp: *useGoCmpFlag}
	if fn.Recv != nil && len(fn.Recv.List) > 0 {
		field := fn.Recv.List[0]
		if len(field.Names) > 0 { info.ReceiverVar = field.Names[0].Name }
		t := field.Type
		if p, ok := t.(*ast.StarExpr); ok { info.IsPointer = true; t = p.X }
		info.ReceiverTypeName = getTypeName(t)
		if info.ReceiverVar == "" { info.ReceiverVar = strings.ToLower(info.ReceiverTypeName[:1]) }
		if st, ok := structs[info.ReceiverTypeName]; ok && st.Fields != nil {
			for _, f := range st.Fields.List {
				for _, n := range f.Names {
					info.ReceiverFields = append(info.ReceiverFields, Param{Name: n.Name, Type: typeToString(f.Type)})
				}
			}
		}
	}
	p := "Test"
	if info.ReceiverTypeName != "" {
		if !ast.IsExported(info.ReceiverTypeName) { p = "Test_" }
		info.TestName = p + info.ReceiverTypeName + "_" + info.Name
	} else {
		if !ast.IsExported(info.Name) { p = "Test_" }
		info.TestName = p + info.Name
	}
	if fn.Type.Params != nil {
		for _, field := range fn.Type.Params.List {
			for _, name := range field.Names {
				info.Args = append(info.Args, Param{Name: name.Name, Type: typeToString(field.Type)})
			}
		}
	}
	if fn.Type.Results != nil {
		for i, field := range fn.Type.Results.List {
			tStr := typeToString(field.Type)
			if tStr == "error" { info.ReturnsError = true; continue }
			if len(field.Names) == 0 {
				w, g := "want", "got"
				if i > 0 || (i == 0 && info.ReturnsError) { w, g = fmt.Sprintf("want%d", i), fmt.Sprintf("got%d", i) }
				info.Results = append(info.Results, Param{Type: tStr, WantName: w, GotName: g})
			} else {
				for _, n := range field.Names {
					info.Results = append(info.Results, Param{Type: tStr, WantName: "want" + strings.Title(n.Name), GotName: "got" + strings.Title(n.Name)})
				}
			}
		}
	}
	return info
}

