		{{- end}}
		{{- if .ReturnsError}}
		wantErr bool
		{{- end}}
	}{
		// TODO: Add test cases.
	}
	for {{if .Named}}name{{else}}_{{end}}, tt := range tests {
		{{- if .Subtests}}
		t.Run({{if .Named}}name{{else}}tt.name{{end}}, func(t *testing.T) {
		{{- end}}
			{{- if .Parallel}}
			t.Parallel()
			{{- end}}
			{{- if .ReceiverFields}}
			{{.ReceiverVar}} := {{if .IsPointer}}&{{end}}{{.ReceiverTypeName}}{
				{{- range .ReceiverFields}}
				{{.Name}}: tt.fields.{{.Name}},
				{{- end}}
			}
			{{- else if .ReceiverTypeName}}
			{{.ReceiverVar}} := {{if .IsPointer}}&{{end}}{{.ReceiverTypeName}}{}
			{{- end}}
			{{- if and (eq (len .Results) 1) (not .ReturnsError)}}
			if got := {{if .ReceiverVar}}{{.ReceiverVar}}.{{end}}{{.Name}}({{range $i, $v := .Args}}{{if $i}}, {{end}}tt.args.{{$v.Name}}{{end}}); got != tt.{{(index .Results 0).WantName}} {
				t.Errorf("{{if $.Subtests}}{{$.Name}}(){{else}}%q. {{$.Name}}(){{end}} = %v, want %v", {{if not $.Subtests}}tt.name, {{end}}got, tt.{{(index .Results 0).WantName}})
			}
			{{- else}}
			{{range $i, $v := .Results}}{{if $i}}, {{end}}{{$v.GotName}}{{end}}{{if .ReturnsError}}, err{{end}} := {{if .ReceiverVar}}{{.ReceiverVar}}.{{end}}{{.Name}}({{range $i, $v := .Args}}{{if $i}}, {{end}}tt.args.{{$v.Name}}{{end}})
			{{- if .ReturnsError}}
			if (err != nil) != tt.wantErr {
				t.{{if $.Subtests}}Fatalf{{else}}Errorf{{end}}("{{if $.Subtests}}{{$.Name}}(){{else}}%q. {{$.Name}}(){{end}} error = %v, wantErr %v", {{if not $.Subtests}}tt.name, {{end}}err, tt.wantErr)
				{{if $.Subtests}}return{{else}}continue{{end}}
			}
			if tt.wantErr {
				return
			}
			{{- end}}
			{{- range .Results}}
			if {{if isComplex .Type}}!reflect.DeepEqual({{.GotName}}, tt.{{.WantName}}){{else}}{{.GotName}} != tt.{{.WantName}}{{end}} {
				t.Errorf("{{if $.Subtests}}{{$.Name}}(){{else}}%q. {{$.Name}}(){{end}} {{if gt (len $.Results) 1}}{{.GotName}} = {{else}}= {{end}}%v, want %v", {{if not $.Subtests}}tt.name, {{end}}{{.GotName}}, tt.{{.WantName}})
			}
			{{- end}}
			{{- end}}
		{{- if .Subtests}}
		})
		{{- end}}
	}
}
`
