func processDir(dir string) {
	files, _ := filepath.Glob(filepath.Join(dir, "*.go"))
	for _, f := range files { if !strings.HasSuffix(f, "_test.go") { processFile(f) } }
}

func processFile(filename string) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, filename, nil, parser.ParseComments)
	if err != nil { return }
	structs := make(map[string]*ast.StructType)
	pkgs, _ := parser.ParseDir(fset, filepath.Dir(filename), nil, 0)
	for _, pkg := range pkgs {
		for _, file := range pkg.Files {
			for _, decl := range file.Decls {
				if gen, ok := decl.(*ast.GenDecl); ok && gen.Tok == token.TYPE {
					for _, spec := range gen.Specs {
						if ts, ok := spec.(*ast.TypeSpec); ok {
							if st, ok := ts.Type.(*ast.StructType); ok { structs[ts.Name.Name] = st }
						}
					}
				}
			}
		}
	}
	var funcs []FuncInfo
	for _, decl := range f.Decls {
		if fn, ok := decl.(*ast.FuncDecl); ok {
			if shouldProcess(fn) { funcs = append(funcs, extractFuncInfo(fn, structs)) }
		}
	}
	if len(funcs) == 0 {
		fmt.Printf("No tests generated for %s\n", filepath.Base(filename))
		return
	}
	generateTests(filename, funcs, f)
}

func shouldProcess(fn *ast.FuncDecl) bool {
	name := fn.Name.Name
	if *exclFlag != "" { if m, _ := regexp.MatchString(*exclFlag, name); m { return false } }
	if *exportedFlag && ast.IsExported(name) { return true }
	if *onlyFlag != "" { if m, _ := regexp.MatchString(*onlyFlag, name); m { return true } }
	return *allFlag
}

func extractFuncInfo(fn *ast.FuncDecl, structs map[string]*ast.StructType) FuncInfo {
	info := FuncInfo{Name: fn.Name.Name, Parallel: *parallelFlag, Subtests: !*nosubtestsFlag, Named: *namedFlag, PrintInputs: *iFlag, UseGoCmp: *useGoCmpFlag, Template: *templateFlag}
	if fn.Recv != nil && len(fn.Recv.List) > 0 {
		field := fn.Recv.List[0]
		if len(field.Names) > 0 { info.ReceiverVar = field.Names[0].Name }
		t := field.Type
		if p, ok := t.(*ast.StarExpr); ok { info.IsPointer = true; t = p.X }
		info.ReceiverTypeName = getTypeName(t)
		if info.ReceiverVar == "" { info.ReceiverVar = strings.ToLower(info.ReceiverTypeName[:1]) }
		if st, ok := structs[info.ReceiverTypeName]; ok && st.Fields != nil {
			for _, f := range st.Fields.List {
				for _, n := range f.Names {
					info.ReceiverFields = append(info.ReceiverFields, Param{Name: n.Name, Type: typeToString(f.Type)})
				}
			}
		}
	}
	p := "Test"
	if info.ReceiverTypeName != "" {
		if !ast.IsExported(info.ReceiverTypeName) { p = "Test_" }
		info.TestName = p + info.ReceiverTypeName + "_" + info.Name
	} else {
		if !ast.IsExported(info.Name) { p = "Test_" }
		info.TestName = p + info.Name
	}
	if fn.Type.Params != nil {
		for _, field := range fn.Type.Params.List {
			for _, name := range field.Names {
				info.Args = append(info.Args, Param{Name: name.Name, Type: typeToString(field.Type)})
			}
		}
	}
	if fn.Type.Results != nil {
		for i, field := range fn.Type.Results.List {
			tStr := typeToString(field.Type)
			if tStr == "error" { info.ReturnsError = true; continue }
			if len(field.Names) == 0 {
				w, g := "want", "got"
				if i > 0 || (i == 0 && info.ReturnsError) { w, g = fmt.Sprintf("want%d", i), fmt.Sprintf("got%d", i) }
				info.Results = append(info.Results, Param{Type: tStr, WantName: w, GotName: g})
			} else {
				for _, n := range field.Names {
					info.Results = append(info.Results, Param{Type: tStr, WantName: "want" + strings.Title(n.Name), GotName: "got" + strings.Title(n.Name)})
				}
			}
		}
	}
	return info
}

func getTypeName(expr ast.Expr) string {
	switch t := expr.(type) {
	case *ast.Ident: return t.Name
	case *ast.IndexExpr: return getTypeName(t.X)
	case *ast.IndexListExpr: return getTypeName(t.X)
	}
	return ""
}

func typeToString(expr ast.Expr) string {
	var buf bytes.Buffer
	format.Node(&buf, token.NewFileSet(), expr)
	return buf.String()
}

func generateTests(filename string, funcs []FuncInfo, f *ast.File) {
	testFilename := strings.TrimSuffix(filename, ".go") + "_test.go"
	existingTests := make(map[string]bool)
	var tf *ast.File
	if _, err := os.Stat(testFilename); err == nil {
		tf, _ = parser.ParseFile(token.NewFileSet(), testFilename, nil, 0)
		for _, decl := range tf.Decls { if fn, ok := decl.(*ast.FuncDecl); ok { existingTests[fn.Name.Name] = true } }
	}

	var funcsToTest []FuncInfo
	for _, fn := range funcs { if !existingTests[fn.TestName] { funcsToTest = append(funcsToTest, fn); fmt.Printf("Generated %s\n", fn.TestName) } }
	if len(funcsToTest) == 0 { if *wFlag { fmt.Printf("No tests generated for %s\n", filepath.Base(filename)) }; if !*wFlag { os.Stdout.Write([]byte{}); } else { return } }

	var buf bytes.Buffer
	if tf == nil {
		buf.WriteString("package " + f.Name.Name + "\n\nimport (\n\t\"testing\"\n")
        needsRef := false
        needsCmp := false
        needsTestify := false
        for _, fn := range funcsToTest {
            if fn.UseGoCmp { needsCmp = true }
            if fn.Template == "testify" { needsTestify = true }
            for _, r := range fn.Results { if isComplex(r.Type) { if fn.UseGoCmp { needsCmp = true } else { needsRef = true } } }
        }
        if needsRef { buf.WriteString("\t\"reflect\"\n") }
        if needsCmp { buf.WriteString("\t\"github.com/google/go-cmp/cmp\"\n") }
        if needsTestify { buf.WriteString("\n\t\"github.com/stretchr/testify/assert\"\n") }
        buf.WriteString(")\n")
	} else {
        existingContent, _ := os.ReadFile(testFilename)
        buf.Write(existingContent)
        buf.WriteString("\n")
    }

	for _, fn := range funcsToTest {
		tmpl, err := template.New("test").Funcs(template.FuncMap{"isComplex": isComplex}).Parse(testTmpl)
        if err != nil { fmt.Fprintf(os.Stderr, "template parse error: %v\n", err); return }
		err = tmpl.Execute(&buf, fn)
        if err != nil { fmt.Fprintf(os.Stderr, "template execute error: %v\n", err); return }
	}

	formatted, err := format.Source(buf.Bytes())
    if err != nil { fmt.Fprintf(os.Stderr, "format error: %v\nOriginal:\n%s\n", err, buf.String()); return }
	if *wFlag { os.WriteFile(testFilename, formatted, 0644) } else { os.Stdout.Write(formatted) }
}

func isComplex(t string) bool {
	return strings.HasPrefix(t, "[]") || strings.HasPrefix(t, "map[") || strings.Contains(t, ".") || (t != "int" && t != "string" && t != "bool" && t != "float64")
