                {{- if .ReturnsError}}
                tt.assertion(t, err)
                {{- end}}
                {{- end}}
            {{- else}}
                {{- if and (eq (len .Results) 1) (not .ReturnsError)}}
                if got := {{if .ReceiverVar}}{{.ReceiverVar}}.{{end}}{{.Name}}({{range $i, $v := .Args}}{{if $i}}, {{end}}tt.args.{{$v.Name}}{{end}}); {{if .UseGoCmp}}!cmp.Equal(got, tt.{{(index .Results 0).WantName}}){{else}}got != tt.{{(index .Results 0).WantName}}{{end}} {
                    t.Errorf("{{if $.Subtests}}{{$.Name}}(){{else}}%q. {{$.Name}}(){{end}} = %v, want %v{{if .UseGoCmp}}\ndiff=%s{{end}}", {{if not $.Subtests}}tt.name, {{end}}got, tt.{{(index .Results 0).WantName}}{{if .UseGoCmp}}, cmp.Diff(tt.{{(index .Results 0).WantName}}, got){{end}})
                }
                {{- else}}
                {{range $i, $v := .Results}}{{if $i}}, {{end}}{{$v.GotName}}{{end}}{{if .ReturnsError}}, err{{end}} := {{if .ReceiverVar}}{{.ReceiverVar}}.{{end}}{{.Name}}({{range $i, $v := .Args}}{{if $i}}, {{end}}tt.args.{{$v.Name}}{{end}})
                {{- if .ReturnsError}}
                if (err != nil) != tt.wantErr {
                    t.{{if $.Subtests}}Fatalf{{else}}Errorf{{end}}("{{if $.Subtests}}{{$.Name}}(){{else}}%q. {{$.Name}}(){{end}} error = %v, wantErr %v", {{if not $.Subtests}}tt.name, {{end}}err, tt.wantErr)
                    {{if $.Subtests}}return{{else}}continue{{end}}
                }
                if tt.wantErr {
                    return
                }
                {{- end}}
                {{- range .Results}}
                if {{if $.UseGoCmp}}!cmp.Equal({{.GotName}}, tt.{{.WantName}}){{else if isComplex .Type}}!reflect.DeepEqual({{.GotName}}, tt.{{.WantName}}){{else}}{{.GotName}} != tt.{{.WantName}}{{end}} {
                    t.Errorf("{{if $.Subtests}}{{$.Name}}(){{else}}%q. {{$.Name}}(){{end}} {{if gt (len $.Results) 1}}{{.GotName}} = {{else}}= {{end}}%v, want %v{{if $.UseGoCmp}}\ndiff=%s{{end}}", {{if not $.Subtests}}tt.name, {{end}}{{.GotName}}, tt.{{.WantName}}{{if $.UseGoCmp}}, cmp.Diff(tt.{{.WantName}}, {{.GotName}}){{end}})
                }
                {{- end}}
                {{- end}}
            {{- end}}
		{{- if .Subtests}}
		})
		{{- end}}
	}
}
